#!/bin/bash
# Categorize port_sweep/link_surface.txt into docs/port/link-surface.md
set -u
cd "$(dirname "$0")/../.."
IN=port_sweep/link_surface.txt
OUT=docs/port/link-surface.md

total=$(wc -l < $IN)
cat > $OUT <<HDR
# Phase 1 Link Surface — the Port Layer's Bill of Materials

*Generated by scripts/port/categorize_surface.sh from the first PC link attempt
(cmake build_pc, all 156 game/engine sources + port/src/main.c; compile clean,
link intentionally unresolved). $total distinct undefined symbols.*

| Category | Distinct symbols | Covered by (PORT-PLAN phase) |
|---|---|---|
HDR

cat_count() { awk '{print $2}' $IN | grep -cE "$1" || true; }

libm=$(cat_count '^(sinf|cosf|sqrtf|atan2f|tanf|floorf|ceilf|fmodf|fabsf)$')
osn=$(cat_count '^(os|__os)')
aln=$(cat_count '^(al|n_al|__al)')
gun=$(cat_count '^(gu|__gu)')
segn=$(cat_count '(_seg$|Segment(Rom)?(Start|End)$)')
animn=$(cat_count '^ANIM_DATA_')
skeln=$(cat_count '^(skeleton_|jointlist_|jointnames_)')
{
echo "| libm float (sinf/cosf/sqrtf…) | $libm | link -lm — free |"
echo "| libultra os* / __os* | $osn | PD libultra.c shim (Phase 2) |"
echo "| audio al* | $aln | AL synth compile + PD mixer (Phase 4) |"
echo "| gu* math | $gun | compile src/libultra/gu C or reimplement (Phase 2) |"
echo "| ROM segment symbols (*_seg, *SegmentStart/End) | $segn | romdata layer (Phase 2) |"
echo "| ANIM_DATA_* animation assets | $animn | romdata/asset layer (Phase 2/6) |"
echo "| skeleton_/jointlist_/jointnames_ model assets | $skeln | generated Model.c data or romdata (Phase 2/6) |"
echo "| other | $((total - libm - osn - aln - gun - segn - animn - skeln)) | triage below |"
} >> $OUT

cat >> $OUT <<'MID'

## Top 40 by reference count

```
MID
head -40 $IN >> $OUT
cat >> $OUT <<'TAIL'
```

## Uncategorized tail (triage list)

```
TAIL
awk '{print $2}' $IN | grep -vE '^(sinf|cosf|sqrtf|atan2f|tanf|floorf|ceilf|fmodf|fabsf)$|^(os|__os|al|n_al|__al|gu|__gu)|(_seg$|Segment(Rom)?(Start|End)$)|^ANIM_DATA_|^(skeleton_|jointlist_|jointnames_)' | head -80 >> $OUT
echo '```' >> $OUT
echo "written $OUT"
grep '|' $OUT | head -10
